param([string]$Version=''); $ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'windows_paths.ps1'); $memoryOps=$PSScriptRoot; $memoryFlag=Join-Path $memoryOps 'maintenance.flag'; $memoryOwnedFlag=[IO.File]::Open($memoryFlag,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None); $memoryOwnedFlag.Dispose(); try { $memoryBefore=& $memoryExe --version; if ($LASTEXITCODE -ne 0) { throw 'Cannot read installed version.' }; $memoryStartup=@(Get-CimInstance Win32_StartupCommand | Where-Object { $_.Name -eq 'ai-memory' -or $_.Name -like 'AI Memory*' } | Select-Object Name,Command,Location,User); $memoryTasks=@(Get-ScheduledTask -TaskName 'AI Memory Health Watch' | ForEach-Object { [pscustomobject]@{name=$_.TaskName;xml=(Export-ScheduledTask -TaskName $_.TaskName -TaskPath $_.TaskPath)} }); [pscustomobject]@{startup=$memoryStartup;tasks=$memoryTasks} | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $memoryOps 'startup-snapshot.json') -Encoding utf8; $memorySnapshotText=& $memoryPython (Join-Path $memoryOps 'upgrade_snapshot.py'); if ($LASTEXITCODE -ne 0) { throw 'Customization backup failed; upgrade not started.' }; $memorySnapshot=$memorySnapshotText | ConvertFrom-Json; $memoryBackup=Join-Path $memorySnapshot.directory 'core.tar.gz'; & $memoryExe --data-dir $memoryData backup --to $memoryBackup; if ($LASTEXITCODE -ne 0) { throw 'Pre-upgrade backup failed; upgrade not started.' }; $memoryCoreText=& $memoryPython (Join-Path $memoryOps 'upgrade_snapshot.py') --verify-core $memoryBackup; if ($LASTEXITCODE -ne 0) { throw 'Core backup verification failed; upgrade not started.' }; $memoryCore=$memoryCoreText | ConvertFrom-Json; [pscustomobject]@{before=$memoryBefore;target=$Version;backup=$memoryBackup;customization=$memorySnapshot;core_verification=$memoryCore;phase='backed-up'} | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $memoryOps 'last-upgrade.json') -Encoding utf8; if ($Version) { & $memoryExe --data-dir $memoryData upgrade --version $Version } else { & $memoryExe --data-dir $memoryData upgrade }; if ($LASTEXITCODE -ne 0) { throw 'Official upgrade failed; inspect installed version and retained backup before retrying.' }; Set-Content -LiteralPath (Join-Path $memoryData 'service-host.stop') -Value 'manual-upgrade'; $memoryTimer=[Diagnostics.Stopwatch]::StartNew(); while ((Test-Path -LiteralPath (Join-Path $memoryData 'service-host.json')) -and $memoryTimer.Elapsed.TotalSeconds -lt 30) { Start-Sleep -Milliseconds 200 }; if (Test-Path -LiteralPath (Join-Path $memoryData 'service-host.json')) { throw 'Host did not stop cooperatively; no force kill attempted.' }; & (Join-Path $memoryOps 'start_native_host.ps1'); if ($LASTEXITCODE -ne 0) { throw 'Native host restart failed.' }; $memoryWait=[Diagnostics.Stopwatch]::StartNew(); $memoryOnline=$false; while (!$memoryOnline -and $memoryWait.Elapsed.TotalSeconds -lt 90) { try { $memoryResponse=Invoke-WebRequest -Uri 'http://127.0.0.1:49374/healthz' -UseBasicParsing -TimeoutSec 2; $memoryOnline=($memoryResponse.StatusCode -eq 200) } catch { Start-Sleep -Milliseconds 500 } }; if (!$memoryOnline) { throw 'Updated service did not pass its health check.' }; $memoryRuntimeText=& $memoryExe --data-dir $memoryData status --json; if ($LASTEXITCODE -ne 0) { throw 'Running server status check failed.' }; $memoryRuntime=$memoryRuntimeText | ConvertFrom-Json; if ($Version -and $memoryRuntime.version -ne $Version.TrimStart('v')) { throw 'Running server version differs from requested version.' }; $memoryAfter=& $memoryExe --version; [pscustomobject]@{before=$memoryBefore;after=$memoryAfter;backup=$memoryBackup;customization=$memorySnapshot;core_verification=$memoryCore;phase='restarted';time_utc=[DateTime]::UtcNow.ToString('o')} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $memoryOps 'last-upgrade.json') -Encoding utf8 } finally { Remove-Item -LiteralPath $memoryFlag -ErrorAction SilentlyContinue; Start-ScheduledTask -TaskName 'AI Memory Health Watch' }
